<div class="content-wrapper" style="min-height: 916px;">    <!-- Content Header (Page header) -->    <section class="content-header">        <h1>Thống kê thưởng</h1>        <ol class="breadcrumb">            <li><a href="/<?php echo ADMIN_URL; ?>"><i class="fa fa-dashboard"></i> Home</a></li>            <li class="active">Thống kê thưởng</li>        </ol>        <div class="box-body">            <div class="form-group" style=" width: 700px;margin-left: 10px">                          <div class="input-group">                    <div class="input-group-addon">                        <i class="fa fa-calendar"></i>                    </div>                    <input  type="text" value="<?php echo $date; ?>" class="form-control pull-right" id="date_install"/>                </div>            </div>                                 </div>           </section>        <!-- Main content -->    <section class="content">        <div class="row">            <div class="col-xs-12">                <div class="box" id="list_ajax">                </div>            </div><!-- /.box -->        </div><!-- /.col -->    </section></div><!-- /.row --><script>    function loadlist() {        var date_install = $('#date_install').val();        $.post('/<?php echo ADMIN_URL; ?>bonus/page', {date_install: date_install}, function (results) {            $('#list_ajax').html(results);        });    }    $("#date_install").daterangepicker({format: 'DD/MM/YYYY', });    $('#date_install').change(function () {        loadlist();    });    loadlist();</script>